\item[S2] Xiaochun Li and Xuerui Yang, \emph{An improvement on Gauss\textquotesingle s Circle Problem and Dirichlet\textquotesingle s Divisor Problem}, arXiv:2308.14859v2 (2023), Section 1, equation (1.1) and ensuing discussion. \url{https://arxiv.org/pdf/2308.14859}.
